insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_143'
from (values
('127.889.d.5.A',3,'A student compares axial-flow, centrifugal and combination compressors on a cutaway display. She is:','["identifying different turbine compressors", "identifying lights", "identifying tires", "identifying seats"]'::jsonb,0,'Compressors.','original'),
('127.889.d.5.A',4,'A centrifugal compressor moves air by:','["heating it", "flinging it outward with a spinning impeller", "freezing it", "pulling it in a line"]'::jsonb,1,'Centrifugal.','original'),
('127.889.d.5.B',3,'A mechanic sorts compressor blades, turbine blades and stator vanes and notes how each is shaped. She is:','["sorting lights", "sorting tires", "identifying different types of turbine engine blades", "sorting seats"]'::jsonb,2,'Blade types.','original'),
('127.889.d.5.B',4,'Turbine blades are made to withstand:','["no load", "cold air only", "low pressure", "very high temperatures and stress"]'::jsonb,3,'Turbine blade stress.','original'),
('127.889.d.5.C',3,'A student tags the inlet, compressor, combustor, turbine and exhaust cone on a turbine model. She is:','["identifying components of turbine engines", "tagging lights", "tagging seats", "tagging tires"]'::jsonb,0,'Engine parts.','original'),
('127.889.d.5.C',4,'The combustor in a turbine engine is where:','["air is cooled", "fuel is burned with compressed air", "fuel is stored", "air is filtered"]'::jsonb,1,'Combustor.','original'),
('127.889.d.5.D',3,'A student draws arrows on a diagram showing how air speeds up and slows down and how pressure rises through the engine. She is:','["describing seats", "describing tires", "mapping airflow direction and pressure changes in turbine engines", "ignoring airflow"]'::jsonb,2,'Airflow map.','original'),
('127.889.d.5.D',4,'In an axial compressor, air pressure:','["stays the same", "vanishes", "drops", "rises as it moves through successive stages"]'::jsonb,3,'Pressure rise.','original'),
('127.889.d.5.E',3,'A mechanic opens the manual to the steps for adjusting the fuel control unit to set idle speed. She is:','["identifying and locating the procedures for the adjustment of a fuel control unit", "ignoring the manual", "guessing", "painting the FCU"]'::jsonb,0,'FCU adjustment.','original'),
('127.889.d.5.E',4,'A fuel control unit meters fuel to the engine based on:','["cabin temperature", "power lever position and engine conditions", "tire pressure", "seat position"]'::jsonb,1,'FCU role.','original'),
('127.889.d.5.F',3,'A mechanic opens the manual to the steps for removing and installing a turbine engine on a wing mount. She is:','["guessing", "painting the engine", "identifying and locating the installation or removal procedures for a turbine engine", "ignoring the manual"]'::jsonb,2,'Engine removal.','original'),
('127.889.d.5.F',4,'When removing a turbine engine, the first step is usually to:','["remove the prop", "add fuel", "start the engine", "disconnect electrical power and drain fluids as directed"]'::jsonb,3,'Removal prep.','original'),
('127.889.d.5.G',3,'A technician examines blades for nicks, erosion and cracks and compares them to the limits in the manual. She is:','["identifying damaged turbine engine blades", "buying blades", "painting blades", "ignoring blades"]'::jsonb,0,'Blade damage.','original'),
('127.889.d.5.G',4,'A blade with a crack beyond the manual''s limits must be:','["blended", "replaced", "painted", "left in place"]'::jsonb,1,'Cracked blade.','original'),
('127.889.d.5.H',3,'A technician studies a drop in thrust and compares inlet damage, dirty blades and worn seals as possible causes. She is:','["painting blades", "ignoring the drop", "analyzing causes for turbine engine performance loss", "guessing"]'::jsonb,2,'Loss analysis.','original'),
('127.889.d.5.H',4,'Worn compressor blade tips can cause a performance loss because they:','["add pressure", "cool the engine", "improve flow", "let air leak past the blades"]'::jsonb,3,'Tip clearance.','original'),
('127.889.d.6.A',3,'A student learns that 100-hour, annual and progressive inspections are set by Part 43 and Part 91 rules. She is explaining:','["the purpose of inspection requirements under 14 CFR Part 43", "no requirements", "shop customs", "optional steps"]'::jsonb,0,'Inspection rules.','original'),
('127.889.d.6.A',4,'Inspection requirements exist to ensure:','["longer breaks", "aircraft stay airworthy", "more profits", "faster repairs"]'::jsonb,1,'Airworthy.','original'),
('127.889.d.6.B',3,'A mechanic reviews the list of parts that must be retired after a set number of hours or cycles. She is explaining:','["avoiding limits", "ignoring parts", "the purpose and methods of identification of life-limited parts", "painting parts"]'::jsonb,2,'Life-limited.','original'),
('127.889.d.6.B',4,'A life-limited part must be removed at its limit even if it:','["is cracked", "is corroded", "is broken", "looks fine"]'::jsonb,3,'Retire on time.','original'),
('127.889.d.6.C',3,'A student studies why an engine must be inspected after a sudden stoppage, such as a propeller strike. She is explaining:','["the purpose and types of special inspections such as sudden engine stoppage", "describing seats", "avoiding inspections", "describing tires"]'::jsonb,0,'Special inspections.','original'),
('127.889.d.6.C',4,'After a propeller strike, the engine should be:','["ignored", "inspected per the manufacturer''s sudden stoppage procedure", "painted", "flown on"]'::jsonb,1,'Sudden stoppage.','original'),
('127.889.d.6.D',3,'A mechanic uses the manufacturer''s overhaul manual instead of a friend''s tip for a repair. She is explaining:','["ignoring manuals", "avoiding data", "the purpose of using FAA-approved data", "picking any source"]'::jsonb,2,'Approved data.','original'),
('127.889.d.6.D',4,'FAA-approved data ensures that a repair is:','["fast", "cheap", "decorative", "acceptable and meets airworthiness standards"]'::jsonb,3,'Why approved.','original'),
('127.889.d.6.E',3,'A mechanic checks that all service letters, bulletins and ADs for an engine were complied with before approving it for return to service. She is explaining:','["the importance of compliance with service letters, service bulletins and ADs", "ignoring them", "guessing", "skipping checks"]'::jsonb,0,'Compliance.','original'),
('127.889.d.6.E',4,'An unaddressed mandatory AD can make an engine:','["lighter", "unairworthy", "cheaper", "more powerful"]'::jsonb,1,'AD risk.','original'),
('127.889.d.6.F',3,'A technician writes the work done, date and signature in the engine logbook per Part 43. She is explaining:','["skipping details", "hiding work", "the purpose of maintenance recordkeeping requirements under 14 CFR Part 43", "avoiding records"]'::jsonb,2,'Records.','original'),
('127.889.d.6.F',4,'Maintenance records are used to:','["help paint", "cool engines", "hide faults", "show what work was done and when"]'::jsonb,3,'Record purpose.','original'),
('127.889.d.6.G',3,'A mechanic runs through a checklist for inspecting, checking and servicing the engine''s oil system, ignition and accessories. She is explaining:','["the purpose of engine component inspection, checking and servicing", "ignoring components", "painting parts", "guessing"]'::jsonb,0,'Component check.','original'),
('127.889.d.6.G',4,'Routine servicing, such as changing oil and filters, helps to:','["hide problems", "extend engine life and catch problems early", "reduce life", "add cost only"]'::jsonb,1,'Servicing value.','original'),
('127.889.d.6.H',3,'A mechanic checks engine mount tubes for cracks and the bolts for correct torque. She is explaining:','["buying mounts", "ignoring mounts", "the importance of inspecting engine mounts and mounting hardware", "painting mounts"]'::jsonb,2,'Engine mounts.','original'),
('127.889.d.6.H',4,'A cracked engine mount can lead to:','["better fit", "longer life", "quieter flight", "the engine shifting or separating from the aircraft"]'::jsonb,3,'Mount crack.','original'),
('127.889.d.6.I',3,'A student reads that a cylinder compression test uses high-pressure air and can turn the propeller. She is researching:','["the risks of performing a compression test on a reciprocating engine", "paint choices", "no risks", "tire brands"]'::jsonb,0,'Compression test risk.','original'),
('127.889.d.6.I',4,'During a compression test, the propeller can suddenly turn, so a technician should:','["stand in line with it", "keep hands and body clear of the propeller arc", "ignore it", "hold the prop"]'::jsonb,1,'Prop turns.','original'),
('127.889.d.6.J',3,'A student learns why adjusting or inspecting an engine while it is running puts hands near rotating parts. She is researching:','["tire brands", "paint choices", "the risks of performing maintenance on an operating reciprocating engine", "no risks"]'::jsonb,2,'Running engine risks.','original'),
('127.889.d.6.J',4,'Loose clothing and jewelry near a running engine are dangerous because they can:','["improve safety", "stay clean", "cool the engine", "be caught by moving parts"]'::jsonb,3,'Loose items.','original'),
('127.889.d.7.A',3,'A student compares an engine''s installed equipment to the type certificate data sheet and the maintenance manual. She is:','["evaluating a powerplant for compliance with FAA-approved or manufacturer data", "ignoring data", "painting parts", "guessing"]'::jsonb,0,'Compliance eval.','original'),
('127.889.d.7.A',4,'A powerplant that doesn''t match its approved data may:','["fly faster", "not be airworthy", "weigh less", "be fine"]'::jsonb,1,'Mismatch.','original'),
('127.889.d.7.B',3,'A mechanic reviews the engine logbook entries and the overhaul records line by line. She is:','["ignoring logs", "painting the engine", "performing a powerplant records inspection", "guessing"]'::jsonb,2,'Records review.','original'),
('127.889.d.7.B',4,'A records inspection looks for:','["seat damage", "paint chips", "tire wear", "missing entries, gaps and uncompleted required work"]'::jsonb,3,'Gaps.','original'),
('127.889.d.7.C',3,'A mechanic checks each applicable AD against the engine''s serial number and logbook to see if it was done. She is:','["inspecting a powerplant for compliance with applicable ADs", "ignoring ADs", "guessing", "painting ADs"]'::jsonb,0,'AD compliance.','original'),
('127.889.d.7.C',4,'An AD applies to an engine based on its:','["color", "make, model and serial number", "mount style", "owner''s name"]'::jsonb,1,'AD applicability.','original'),
('127.889.d.7.D',3,'A shop looks up the engine on the TCDS to see whether it can be installed on a given airframe. She is:','["using memory", "ignoring the TCDS", "determining powerplant installation eligibility in accordance with the TCDS", "guessing"]'::jsonb,2,'TCDS.','original'),
('127.889.d.7.D',4,'The type certificate data sheet lists:','["flight plans", "weather reports", "seat prices", "the approved engines and limits for an aircraft model"]'::jsonb,3,'TCDS content.','original'),
('127.889.d.7.E',3,'A mechanic moves the throttle, mixture and prop controls from stop to stop and confirms the engine responds correctly. She is:','["inspecting engine controls for proper operation and adjustment", "bending controls", "painting controls", "ignoring controls"]'::jsonb,0,'Control check.','original'),
('127.889.d.7.E',4,'If the throttle lever reaches the stop but the engine''s throttle arm does not, the linkage:','["should be ignored", "needs adjustment", "needs painting", "is perfect"]'::jsonb,1,'Linkage fix.','original'),
('127.889.d.7.F',3,'A mechanic checks an engine-driven fuel pump or starter for leaks, wear, mounting and operation. She is:','["painting accessories", "buying accessories", "inspecting an aircraft engine accessory for serviceability", "ignoring accessories"]'::jsonb,2,'Accessory check.','original'),
('127.889.d.7.F',4,'An accessory with leaking seals should be:','["oiled", "ignored", "painted", "repaired or replaced"]'::jsonb,3,'Leaks.','original'),
('127.889.d.7.G',3,'A mechanic adds up the hours and cycles on a turbine disk from the logbook and compares them to the limit. She is:','["inspecting engine records for time or cycles on life-limited parts", "guessing", "ignoring records", "painting disks"]'::jsonb,0,'Cycle tracking.','original'),
('127.889.d.7.G',4,'A turbine disk''s life is usually counted in:','["tire changes", "cycles of start, run and shutdown", "seat rows", "colors"]'::jsonb,1,'Cycles.','original'),
('127.889.d.7.H',3,'A technician starts an engine and watches oil pressure, temperature and rpm against the limits. She is:','["ignoring gauges", "guessing", "performing an engine start and inspecting engine operational parameters", "painting gauges"]'::jsonb,2,'Start and check.','original'),
('127.889.d.7.H',4,'Right after engine start, a technician should watch first for:','["radio noise", "tire pressure", "cabin lights", "oil pressure rising within the specified time"]'::jsonb,3,'Oil pressure.','original'),
('127.889.d.7.I',3,'A mechanic looks over engine mount tubes, rubber isolators and attach bolts for cracks and wear. She is:','["inspecting an engine mount to determine serviceability", "painting the mount", "buying a mount", "ignoring the mount"]'::jsonb,0,'Mount check.','original'),
