('127.889.d.8.A',3,'A student labels the fuel flow gauge, oil pressure gauge, EGT and tachometer on an engine panel. She is:','["labeling tires", "labeling seats", "identifying the components of engine instrument systems", "labeling lights"]'::jsonb,2,'Engine instruments.','original'),
('127.889.d.8.A',4,'A tachometer shows:','["cabin temperature", "fuel level", "oil quantity", "engine or propeller speed in rpm"]'::jsonb,3,'Tach.','original'),
('127.889.d.8.B',3,'A student explains how a fuel flow transmitter sends a signal that the gauge converts to gallons per hour. She is:','["explaining the operational theory of engine instrument systems", "describing seats", "avoiding theory", "describing tires"]'::jsonb,0,'Gauge theory.','original'),
('127.889.d.8.B',4,'An oil temperature gauge usually relies on a:','["camera", "probe whose resistance changes with temperature", "compass", "tire"]'::jsonb,1,'Temp sensor.','original'),
('127.889.d.8.C',3,'A student compares a warning light, a caution light and an advisory light on a panel. She is:','["describing seats", "describing tires", "describing the types of annunciator indicators and their functions", "avoiding lights"]'::jsonb,2,'Annunciators.','original'),
('127.889.d.8.C',4,'An annunciator panel''s job is to:','["store oil", "hold fuel", "cool the cockpit", "alert the crew to system conditions"]'::jsonb,3,'Annunciator role.','original'),
('127.889.d.8.D',3,'A student learns that red usually means warning, amber caution and green or white advisory. She is:','["defining the meaning of annunciator warning, caution and advisory indications", "describing seats", "describing tires", "ignoring lights"]'::jsonb,0,'Color meanings.','original'),
('127.889.d.8.D',4,'A caution annunciator generally means the crew should:','["do nothing ever", "be aware and take action soon", "land immediately", "ignore it"]'::jsonb,1,'Caution.','original'),
('127.889.d.8.E',3,'A student studies a FADEC that controls fuel and engine settings automatically with two redundant channels. She is:','["describing tires", "avoiding FADEC", "identifying the components and explaining the operational theory of full authority digital engine control", "describing seats"]'::jsonb,2,'FADEC.','original'),
('127.889.d.8.E',4,'FADEC systems use redundant channels so that:','["one failure stops everything", "fuel stops", "engines run without control", "a single failure does not stop engine control"]'::jsonb,3,'Redundancy.','original'),
('127.889.d.8.F',3,'A mechanic checks that the green arc, yellow arc and red line on an oil pressure gauge match the engine''s limits. She is:','["explaining the purpose and methods of marking engine instrument ranges", "painting arcs randomly", "guessing", "ignoring limits"]'::jsonb,0,'Range marks.','original'),
('127.889.d.8.F',4,'A red line on an engine gauge marks:','["a sensor", "a maximum or minimum operating limit", "a caution range", "a normal range"]'::jsonb,1,'Red line.','original'),
('127.889.d.8.G',3,'A student learns that using the wrong cleaner or a rough touch on instrument faces and sensor lines can break them. She is researching:','["paint choices", "no risks", "the risks of damaging instrument systems or indicating systems", "tire brands"]'::jsonb,2,'Instrument damage.','original'),
('127.889.d.8.G',4,'Pulling on a sensor wire or bending a pitot or probe line can:','["cool the engine", "improve readings", "clean the line", "damage the instrument system"]'::jsonb,3,'Handle with care.','original'),
('127.889.d.8.H',3,'A student reads that an engine gauge reading too low could hide a hot engine from the pilot. She is researching:','["the risks of inaccurate engine instrument calibration or indication", "no risks", "paint choices", "tire brands"]'::jsonb,0,'Bad calibration.','original'),
('127.889.d.8.H',4,'An EGT gauge that reads lower than actual could lead a pilot to:','["protect the engine", "overheat the engine without knowing", "cool the engine", "save fuel always"]'::jsonb,1,'Under-reading.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
